{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPHFPw7PPJ9mhlbWLKx6OEG"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"b5ZvnNBInaUi","executionInfo":{"status":"ok","timestamp":1784635250366,"user_tz":-480,"elapsed":27202,"user":{"displayName":"Vicky.F Kheo","userId":"00762162888805970006"}},"outputId":"7ef4e03b-4faa-49ea-80ec-9d429f7e3e72","colab":{"base_uri":"https://localhost:8080/"}},"outputs":[{"output_type":"stream","name":"stdout","text":["\u001b[2K   \u001b[90m━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\u001b[0m \u001b[32m349.5/349.5 kB\u001b[0m \u001b[31m5.7 MB/s\u001b[0m eta \u001b[36m0:00:00\u001b[0m\n","\u001b[2K   \u001b[90m━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\u001b[0m \u001b[32m153.3/153.3 kB\u001b[0m \u001b[31m3.6 MB/s\u001b[0m eta \u001b[36m0:00:00\u001b[0m\n","\u001b[2K   \u001b[90m━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\u001b[0m \u001b[32m3.1/3.1 MB\u001b[0m \u001b[31m15.3 MB/s\u001b[0m eta \u001b[36m0:00:00\u001b[0m\n","\u001b[?25h"]}],"source":["import re\n","import csv\n","import logging\n","from pathlib import Path\n","from datetime import datetime\n","from io import BytesIO\n","\n","import pandas as pd\n","import pytz\n","import streamlit as st\n","from fuzzywuzzy import fuzz\n","from pypdf import PdfReader\n","from pypdf.errors import PdfReadError\n","from sklearn.feature_extraction.text import TfidfVectorizer\n","from sklearn.metrics.pairwise import cosine_similarity\n","\n","logging.getLogger(\"pypdf\").setLevel(logging.ERROR)\n","\n","st.set_page_config(page_title=\"Procurement Integrity Platform\", layout=\"wide\")\n","st.title(\"Procurement Integrity Platform\")\n","st.write(\"Upload quotation PDFs and run metadata, similarity, and risk checks.\")\n","\n","\n","def dt_now() -> str:\n","    return datetime.now().strftime(\"%Y%m%d%H%M%S\")\n","\n","\n","def parse_pdf_date(dt_str: str) -> str:\n","    if not dt_str:\n","        return \"\"\n","    try:\n","        val = str(dt_str).strip().replace(\"D:\", \"\").replace(\"'\", \"\")\n","        if \"Z\" in val:\n","            val = val.split(\"Z\")[0]\n","\n","        dt = pd.to_datetime(val, errors=\"coerce\")\n","        if pd.isna(dt):\n","            return \"\"\n","\n","        if dt.tzinfo is not None:\n","            dt = dt.tz_convert(\"Asia/Singapore\")\n","        else:\n","            dt = dt.tz_localize(\"Asia/Singapore\")\n","\n","        return dt.strftime(\"%Y-%m-%d %H:%M:%S\")\n","    except Exception:\n","        return \"\"\n","\n","\n","def parse_file_id(name_of_file: str) -> dict:\n","    result_fields = [\"Has Identifiers\", \"Tender ID\", \"Vendor ID\", \"Reference Name\"]\n","    identifiers = name_of_file.split(\"_\")[:3]\n","\n","    if len(identifiers) < 3 or all(x == \"\" for x in identifiers[:2]):\n","        return dict(zip(result_fields, [\"FALSE\"] + [\"\"] * 3))\n","\n","    return dict(zip(result_fields, [\"TRUE\"] + [x for x in identifiers]))\n","\n","\n","def extract_metadata(reader: PdfReader) -> dict:\n","    doc_metadata = reader.metadata or {}\n","    field_mapping = {\n","        \"Author\": \"/Author\",\n","        \"PDF Application\": \"/Creator\",\n","        \"PDF Producer\": \"/Producer\",\n","        \"Created Date\": \"/CreationDate\",\n","        \"Modified Date\": \"/ModDate\",\n","        \"Title\": \"/Title\",\n","        \"Subject\": \"/Subject\",\n","        \"Keywords\": \"/Keywords\",\n","    }\n","\n","    data = {k: doc_metadata.get(v, \"\") for k, v in field_mapping.items()}\n","\n","    for k in (\"Created Date\", \"Modified Date\"):\n","        data[k] = parse_pdf_date(data[k])\n","\n","    return data\n","\n","\n","def extract_annotations(reader: PdfReader) -> dict:\n","    buffer = []\n","\n","    if reader.pages:\n","        for page in reader.pages:\n","            annots = getattr(page, \"annotations\", None)\n","            if not annots:\n","                continue\n","\n","            for annot in annots:\n","                if annot.get(\"/Subtype\") in (\"/Link\", \"/Popup\"):\n","                    continue\n","                buffer.append({\n","                    \"Annotation Type\": annot.get(\"/Subtype\", \"unknown\"),\n","                    \"Author\": annot.get(\"/T\"),\n","                    \"Position\": annot.get(\"/Rect\"),\n","                    \"Created Date\": annot.get(\"/CreationDate\"),\n","                    \"Modified Date\": annot.get(\"/M\"),\n","                })\n","\n","    annot_summary = set(x.get(\"Annotation Type\") for x in buffer) if buffer else set()\n","\n","    return {\n","        \"Annotations Summary\": str(annot_summary),\n","        \"Number of Annotations\": len(buffer),\n","        \"Annotation Details\": str(buffer) if buffer else \"\",\n","    }\n","\n","\n","def extract_pdf_info_from_upload(uploaded_file) -> dict:\n","    try:\n","        reader = PdfReader(BytesIO(uploaded_file.read()))\n","    except PdfReadError:\n","        return {\n","            \"Filename\": uploaded_file.name,\n","            \"Number of Pages\": 0,\n","            \"Has Identifiers\": \"\",\n","            \"Tender ID\": \"\",\n","            \"Vendor ID\": \"\",\n","            \"Reference Name\": \"\",\n","            \"Author\": \"\",\n","            \"PDF Application\": \"\",\n","            \"PDF Producer\": \"\",\n","            \"Created Date\": \"\",\n","            \"Modified Date\": \"\",\n","            \"Title\": \"\",\n","            \"Subject\": \"\",\n","            \"Keywords\": \"\",\n","            \"PDF Version\": \"\",\n","            \"Annotations Summary\": \"\",\n","            \"Number of Annotations\": \"\",\n","            \"Annotation Details\": \"\",\n","            \"Full Text\": \"\",\n","        }\n","\n","    full_text = []\n","    for page in reader.pages:\n","        try:\n","            page_text = page.extract_text() or \"\"\n","        except Exception:\n","            page_text = \"\"\n","        if page_text:\n","            full_text.append(page_text)\n","\n","    return {\n","        \"Filename\": uploaded_file.name,\n","        \"Number of Pages\": len(reader.pages),\n","        **parse_file_id(Path(uploaded_file.name).stem),\n","        **extract_metadata(reader),\n","        \"PDF Version\": reader.pdf_header,\n","        **extract_annotations(reader),\n","        \"Full Text\": \"\\n\".join(full_text).strip(),\n","    }\n","\n","\n","def fuzzy_match(string1: str, string2: str) -> int:\n","    if string1 == \"\" or string2 == \"\":\n","        return 0\n","\n","    string1 = \"\".join(string1.lower().split(\" \"))\n","    string2 = \"\".join(string2.lower().split(\" \"))\n","    string1 = re.sub(r\"[^a-zA-Z0-9\\s]\", \"\", string1)\n","    string2 = re.sub(r\"[^a-zA-Z0-9\\s]\", \"\", string2)\n","\n","    return fuzz.token_sort_ratio(string1, string2)\n","\n","\n","def is_similar(string_1: str, string_2: str, threshold: int = 80) -> bool:\n","    return fuzzy_match(string_1, string_2) > threshold\n","\n","\n","def derive_risk_flags(pdf_data: pd.DataFrame) -> pd.DataFrame:\n","    df = pdf_data.copy()\n","\n","    def safe_prefix(val):\n","        val = \"\" if pd.isna(val) else str(val)\n","        return val[:10]\n","\n","    df[\"Modified After Creation\"] = df.apply(\n","        lambda row: str(not (\n","            safe_prefix(row.get(\"Created Date\", \"\")) ==\n","            safe_prefix(row.get(\"Modified Date\", \"\"))\n","        )).upper(),\n","        axis=1\n","    )\n","\n","    df_author = df[df[\"Author\"].notna() & (df[\"Author\"] != \"\")]\n","    counts = df_author[\"Author\"].value_counts()\n","    author_checks = counts[counts > 1].index\n","    df[\"Same Author Across Different Documents\"] = df[\"Author\"].isin(\n","        author_checks\n","    ).astype(str).str.upper()\n","\n","    df_author_vendor = df[\n","        df[\"Has Identifiers\"].notna() & (df[\"Has Identifiers\"] != \"\") &\n","        df[\"Vendor ID\"].notna() & (df[\"Vendor ID\"] != \"\") &\n","        df[\"Author\"].notna() & (df[\"Author\"] != \"\")\n","    ]\n","    counts = df_author_vendor.groupby(\"Author\")[\"Vendor ID\"].nunique()\n","    author_vendor_check = counts[counts > 1].index\n","\n","    df[\"Same Author Across Different Vendors\"] = df.apply(\n","        lambda x: (\n","            \"TRUE\" if x[\"Has Identifiers\"] == \"TRUE\" and\n","            x[\"Author\"] in author_vendor_check else \"FALSE\"\n","        ),\n","        axis=1\n","    )\n","\n","    similar_idx = []\n","    for index, row in df_author_vendor.iterrows():\n","        for i, r in df_author_vendor.iterrows():\n","            if index == i:\n","                continue\n","            if row[\"Vendor ID\"] != r[\"Vendor ID\"] and is_similar(row[\"Author\"], r[\"Author\"]):\n","                similar_idx.append((row[\"Vendor ID\"], row[\"Author\"]))\n","\n","    similar_idx = set(similar_idx)\n","    df[\"Similar Author Across Different Vendors\"] = df.apply(\n","        lambda row: str((row[\"Vendor ID\"], row[\"Author\"]) in similar_idx).upper(),\n","        axis=1\n","    )\n","\n","    df_appln_vendor = df[\n","        df[\"Has Identifiers\"].notna() & (df[\"Has Identifiers\"] != \"\") &\n","        df[\"Vendor ID\"].notna() & (df[\"Vendor ID\"] != \"\") &\n","        df[\"PDF Application\"].notna() & (df[\"PDF Application\"] != \"\")\n","    ]\n","    counts = df_appln_vendor.groupby(\"PDF Application\")[\"Vendor ID\"].nunique()\n","    appln_vendor_check = counts[counts > 1].index\n","    df[\"Same PDF Application Across Different Vendors\"] = df.apply(\n","        lambda x: (\n","            \"TRUE\" if x[\"Has Identifiers\"] == \"TRUE\" and\n","            x[\"PDF Application\"] in appln_vendor_check else \"FALSE\"\n","        ),\n","        axis=1\n","    )\n","\n","    df_producer_vendor = df[\n","        df[\"Has Identifiers\"].notna() & (df[\"Has Identifiers\"] != \"\") &\n","        df[\"Vendor ID\"].notna() & (df[\"Vendor ID\"] != \"\") &\n","        df[\"PDF Producer\"].notna() & (df[\"PDF Producer\"] != \"\")\n","    ]\n","    counts = df_producer_vendor.groupby(\"PDF Producer\")[\"Vendor ID\"].nunique()\n","    producer_vendor_check = counts[counts > 1].index\n","    df[\"Same PDF Producer Across Different Vendors\"] = df.apply(\n","        lambda x: (\n","            \"TRUE\" if x[\"Has Identifiers\"] == \"TRUE\" and\n","            x[\"PDF Producer\"] in producer_vendor_check else \"FALSE\"\n","        ),\n","        axis=1\n","    )\n","\n","    return df\n","\n","\n","def build_pairwise_similarity_table(df: pd.DataFrame, threshold: float = 0.75) -> pd.DataFrame:\n","    work_df = df.copy()\n","    texts = work_df[\"Full Text\"].fillna(\"\").tolist()\n","\n","    if len(texts) < 2:\n","        return pd.DataFrame(columns=[\"File A\", \"File B\", \"Similarity\", \"Flag\"])\n","\n","    vectorizer = TfidfVectorizer(stop_words=\"english\")\n","    matrix = vectorizer.fit_transform(texts)\n","    sim_matrix = cosine_similarity(matrix)\n","\n","    rows = []\n","    for i in range(len(work_df)):\n","        for j in range(i + 1, len(work_df)):\n","            score = float(sim_matrix[i, j])\n","            rows.append({\n","                \"File A\": work_df.loc[i, \"Filename\"],\n","                \"File B\": work_df.loc[j, \"Filename\"],\n","                \"Similarity\": round(score, 4),\n","                \"Flag\": \"TRUE\" if score >= threshold else \"FALSE\"\n","            })\n","\n","    pairwise_df = pd.DataFrame(rows)\n","    if not pairwise_df.empty:\n","        pairwise_df = pairwise_df.sort_values(\"Similarity\", ascending=False)\n","\n","    return pairwise_df\n","\n","\n","def add_overall_risk_score(df: pd.DataFrame, pairwise_df: pd.DataFrame) -> pd.DataFrame:\n","    work_df = df.copy()\n","\n","    work_df[\"Metadata Flags Count\"] = (\n","        (work_df[\"Modified After Creation\"] == \"TRUE\").astype(int)\n","        + (work_df[\"Same Author Across Different Documents\"] == \"TRUE\").astype(int)\n","        + (work_df[\"Same Author Across Different Vendors\"] == \"TRUE\").astype(int)\n","        + (work_df[\"Similar Author Across Different Vendors\"] == \"TRUE\").astype(int)\n","        + (work_df[\"Same PDF Application Across Different Vendors\"] == \"TRUE\").astype(int)\n","        + (work_df[\"Same PDF Producer Across Different Vendors\"] == \"TRUE\").astype(int)\n","    )\n","\n","    work_df[\"High Similarity Pair Count\"] = 0 if pairwise_df.empty else int((pairwise_df[\"Flag\"] == \"TRUE\").sum())\n","\n","    def risk_label(row):\n","        score = row[\"Metadata Flags Count\"] + row[\"High Similarity Pair Count\"]\n","        if score >= 4:\n","            return \"High\"\n","        if score >= 2:\n","            return \"Medium\"\n","        return \"Low\"\n","\n","    work_df[\"Overall Risk\"] = work_df.apply(risk_label, axis=1)\n","    return work_df\n","\n","\n","def process_uploaded_pdfs(uploaded_files):\n","    pdf_extracts = [extract_pdf_info_from_upload(f) for f in uploaded_files]\n","    pdf_extracts = [f for f in pdf_extracts if f]\n","\n","    if not pdf_extracts:\n","        raise ValueError(\"No readable PDF files uploaded\")\n","\n","    pdf_data = pd.DataFrame(pdf_extracts)\n","    pdf_data = derive_risk_flags(pdf_data)\n","\n","    pairwise_df = build_pairwise_similarity_table(pdf_data, threshold=0.75)\n","    pdf_data = add_overall_risk_score(pdf_data, pairwise_df)\n","\n","    return pdf_data, pairwise_df\n","\n","\n","uploaded_files = st.file_uploader(\n","    \"Upload quotation PDFs\",\n","    type=[\"pdf\"],\n","    accept_multiple_files=True\n",")\n","\n","run = st.button(\"Run Analysis\")\n","\n","if run:\n","    if not uploaded_files:\n","        st.warning(\"Please upload at least one PDF.\")\n","    else:\n","        result_df, pairwise_df = process_uploaded_pdfs(uploaded_files)\n","        result_df = result_df.sort_values(\"Filename\")\n","\n","        c1, c2, c3 = st.columns(3)\n","        c1.metric(\"Documents\", len(result_df))\n","        c2.metric(\"High Risk Docs\", int((result_df[\"Overall Risk\"] == \"High\").sum()))\n","        c3.metric(\"High Similarity Pairs\", int((pairwise_df[\"Flag\"] == \"TRUE\").sum()) if not pairwise_df.empty else 0)\n","\n","        st.subheader(\"Document Metadata and Risk Flags\")\n","        cols_to_show = [\n","            \"Filename\", \"Vendor ID\", \"Author\", \"PDF Application\", \"PDF Producer\",\n","            \"Modified After Creation\", \"Same Author Across Different Documents\",\n","            \"Same PDF Application Across Different Vendors\",\n","            \"Same PDF Producer Across Different Vendors\",\n","            \"Overall Risk\"\n","        ]\n","        st.dataframe(result_df[cols_to_show], use_container_width=True)\n","\n","        st.subheader(\"Pairwise Similarity Results\")\n","        st.dataframe(pairwise_df, use_container_width=True)\n","\n","        meta_csv = result_df.to_csv(index=False, encoding=\"utf-8-sig\").encode(\"utf-8-sig\")\n","        pair_csv = pairwise_df.to_csv(index=False, encoding=\"utf-8-sig\").encode(\"utf-8-sig\")\n","\n","        st.download_button(\n","            \"Download Metadata Results CSV\",\n","            data=meta_csv,\n","            file_name=f\"metadata_results_{dt_now()}.csv\",\n","            mime=\"text/csv\"\n","        )\n","\n","        st.download_button(\n","            \"Download Pairwise Results CSV\",\n","            data=pair_csv,\n","            file_name=f\"pairwise_results_{dt_now()}.csv\",\n","            mime=\"text/csv\"\n","        )"]}]}